This page has no data source for the four output fields, so it renders them empty. `ScreenProps` carries only `api` and `navigate`, and the only client operation, `payOrder`, needs a full payment request that this screen never collects. I did not call it or invent values, and the prototype's sample scenarios are left out. If the payment screen is meant to hand its result to this page, the shell needs to pass it in.

I used `SCR-PAGOORD` for NUEVO PAGO and `SCR-PAGOMEN` for MENU, taken from the prototype, since the contract lists no targets. `KeyBar` and the other components outside your list are left out, so the two buttons are the only `data-action` elements.

```tsx
import type { FormEvent, ReactNode } from 'react'
import { Screen, Card, Grid, Stack, Button } from '@nexti/ds'
import type { ScreenProps } from './types'

interface OutputProps {
  name: string
  label: string
  children?: ReactNode
}

function OutputValue({ name, label, children }: OutputProps) {
  return (
    <div data-field={name} style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
      <span style={{ fontSize: 13, color: '#555' }}>{label}</span>
      <p
        aria-label={label}
        style={{ margin: 0, fontSize: 18, fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}
      >
        {children}
      </p>
    </div>
  )
}

// The page receives no payment result from the shell (ScreenProps carries only
// `api` and `navigate`), so the output fields start empty.
const RESULT = {
  RORDEN: '',
  RCOMIS: '',
  RMOVIM: '',
  RMENS: '',
}

export default function PagoresScreen({ navigate }: ScreenProps) {
  const newPayment = () => navigate('SCR-PAGOORD')
  const menu = () => navigate('SCR-PAGOMEN')

  const onSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    newPayment()
  }

  return (
    <Screen title="Resultado del pago" code="PAGORES">
      <form onSubmit={onSubmit} noValidate>
        <Stack>
          <Card title="Detalle del resultado">
            <Grid columns={2}>
              <OutputValue name="RORDEN" label="Orden">
                {RESULT.RORDEN}
              </OutputValue>
              <OutputValue name="RMOVIM" label="Movimiento">
                {RESULT.RMOVIM}
              </OutputValue>
              <OutputValue name="RCOMIS" label="Comisión">
                {RESULT.RCOMIS}
              </OutputValue>
              <OutputValue name="RMENS" label="Resultado">
                {RESULT.RMENS}
              </OutputValue>
            </Grid>
          </Card>

          <div style={{ display: 'flex', gap: 8 }}>
            <Button type="submit" variant="primary" data-action="ENTER">
              Nuevo pago
            </Button>
            <Button type="button" variant="secondary" data-action="PF3" onClick={menu}>
              Menú
            </Button>
          </div>
        </Stack>
      </form>
    </Screen>
  )
}
```
